//   - The only behaviour that is inherently document-wide in the original
//     code (the emphasis replacement) is factored out into renderEmphasis
//     and applied per line, which is also what real markdown expects.
func Render(markdown string) string {
	var html strings.Builder
	inList := false

	// closeList terminates the current <ul>, if any.
	closeList := func() {
		if inList {
			html.WriteString("</ul>")
			inList = false
		}
	}

	for _, line := range strings.Split(markdown, "\n") {
		if line == "" {
			// A blank line ends the current list but produces no HTML of its own.
			closeList()
			continue
