// and the first "_text_" pair to <em>text</em>.
//
// This is the same replacement the original implementation performed (via
// strings.Replace with a count of 1); it is simply isolated here.
func renderEmphasis(s string) string {
	s = strings.Replace(s, "__", "<strong>", 1)
	s = strings.Replace(s, "__", "</strong>", 1)
	s = strings.Replace(s, "_", "<em>", 1)
	s = strings.Replace(s, "_", "</em>", 1)
	return s
}

// renderHeader renders a line that begins with one or more '#' characters.
// One to six hashes produce an <hN> heading. Seven or more hashes are not a
