package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes (see .docs/instructions.md):
//
// The original implementation walked the input one byte at a time in a single
// loop, tracking headers, lists and paragraphs with a tangle of flags and
// index arithmetic. It has been rewritten to process the input line by line:
//
//   - each line is rendered independently as a heading, a list item or a
//     paragraph;
//   - the only state carried between lines is whether a list is open, so a
//     <ul> is opened at the first "* " line and closed when the list ends;
//   - the emphasis replacement, which the original code applied to the whole
//     document, is factored out into renderEmphasis and applied per line.
//
// All test cases produce the same output as before the refactor.
func Render(markdown string) string {
	var html strings.Builder
	inList := false

	// closeList terminates the list we are currently in, if any.
	closeList := func() {
		if inList {
			html.WriteString("</ul>")
			inList = false
		}
	}

	for _, line := range strings.Split(markdown, "\n") {
		if line == "" {
			// A blank line ends the current list but renders nothing itself.
			closeList()
			continue
		}

		line = renderEmphasis(line)

		switch {
		case strings.HasPrefix(line, "#"):
			closeList()
			html.WriteString(renderHeader(line))
		case strings.HasPrefix(line, "* "):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + strings.TrimPrefix(line, "* ") + "</li>")
		default:
			closeList()
			html.WriteString("<p>" + line + "</p>")
		}
	}

	closeList()
	return html.String()
}

// renderEmphasis converts the first "__text__" pair to <strong>text</strong>
// and the first "_text_" pair to <em>text</em>.
//
// These are exactly the replacements the original implementation performed
// (strings.Replace with a count of 1); they are isolated here so the main
// loop can stay focused on block structure.
func renderEmphasis(s string) string {
	s = strings.Replace(s, "__", "<strong>", 1)
	s = strings.Replace(s, "__", "</strong>", 1)
	s = strings.Replace(s, "_", "<em>", 1)
	s = strings.Replace(s, "_", "</em>", 1)
	return s
}

// renderHeader renders a line that starts with one or more '#' characters.
//
// One to six hashes produce an <hN> heading. Seven or more hashes are not a
// valid heading level, so the hashes are kept as literal text in a paragraph,
// matching the original behaviour.
func renderHeader(line string) string {
	level := 0
	for strings.HasPrefix(line, "#") {
		level++
		line = line[1:]
	}
	line = strings.TrimPrefix(line, " ")

	if level >= 7 {
		hashes := strings.Repeat("#", level)
		if line == "" {
			return "<p>" + hashes + "</p>"
		}
		return fmt.Sprintf("<p>%s %s", hashes, line)
	}
	return fmt.Sprintf("<h%d>%s</h%d>", level, line, level)
}

